/// Playlists songs can be added to: not generated by the server, not deleted,
/// and owned by this user (a public playlist of someone else is read-only).
final editablePlaylistsProvider =
    Provider.autoDispose<List<PlaylistRow>>((ref) {
  final all = ref.watch(playlistsProvider).value ?? const [];
  final me = ref.watch(activeServerProvider).value?.username;
  return [
    for (final p in all)
      if (!p.readonly && (p.owner == null || p.owner == me)) p,
  ];
});

/// Whether [playlist] can be changed from this phone.
bool isEditablePlaylist(PlaylistRow playlist, String? username) =>
    !playlist.readonly &&
    playlist.deletedAtMs == null &&
    (playlist.owner == null || playlist.owner == username);

/// Asks for a playlist name; `null` when the user cancels.
Future<String?> promptPlaylistName(
  BuildContext context, {
  String title = 'New playlist',
  String? initial,
  String confirmLabel = 'Create',
}) {
  return showDialog<String>(
    context: context,
    builder: (_) => _NameDialog(
      title: title,
      initial: initial,
      confirmLabel: confirmLabel,
    ),
  );
}

class _NameDialog extends StatefulWidget {
  const _NameDialog({
    required this.title,
    required this.confirmLabel,
    this.initial,
  });

  final String title;
  final String confirmLabel;
  final String? initial;

  @override
  State<_NameDialog> createState() => _NameDialogState();
}

class _NameDialogState extends State<_NameDialog> {
  late final TextEditingController _controller =
      TextEditingController(text: widget.initial ?? '');

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  void _submit() {
    final name = _controller.text.trim();
    Navigator.of(context).pop(name.isEmpty ? null : name);
  }

  @override
  Widget build(BuildContext context) {
    return AlertDialog(
      title: Text(widget.title),
      content: TextField(
        controller: _controller,
        autofocus: true,
        textCapitalization: TextCapitalization.sentences,
        decoration: const InputDecoration(hintText: 'Playlist name'),
        onSubmitted: (_) => _submit(),
      ),
      actions: [
        TextButton(
          onPressed: () => Navigator.of(context).pop(),
          child: const Text('Cancel'),
        ),
        FilledButton(onPressed: _submit, child: Text(widget.confirmLabel)),
      ],
    );
  }
}

void _toast(BuildContext context, String message) {
  ScaffoldMessenger.of(context)
    ..hideCurrentSnackBar()
    ..showSnackBar(SnackBar(content: Text(message)));
}

/// Creates a playlist (asking for its name) holding [trackIds].
///
/// Returns the new playlist's id, or `null` when cancelled. [open] jumps to
/// the new playlist afterwards (used when it was created empty from the
/// Library, where the next step is filling it).
Future<String?> createPlaylistFlow(
  BuildContext context, {
  List<String> trackIds = const [],
  String? suggestedName,
  bool open = false,
}) async {
  // The widget that started this may be a bottom sheet that is gone by the
  // time the dialog closes, so providers are read through the container.
  final container = ProviderScope.containerOf(context, listen: false);
  final name = await promptPlaylistName(context, initial: suggestedName);
  if (name == null || !context.mounted) return null;
  final session = await container.read(sessionProvider.future);
  if (session == null || !context.mounted) return null;
  final id = await session.playlists.create(name, trackIds: trackIds);
  if (!context.mounted) return id;
  unawaited(HapticFeedback.mediumImpact());
  if (open) {
    Nav.playlist(context, id);
  } else {
    _toast(
      context,
      trackIds.isEmpty
          ? 'Created "$name"'
          : 'Added ${plural(trackIds.length, 'song')} to "$name"',
    );
  }
  return id;
}

/// Bottom sheet to pick a playlist (or make a new one) for [trackIds].
Future<void> showAddToPlaylistSheet(
  BuildContext context, {
  required List<String> trackIds,
  String? suggestedName,
}) {
  return showModalBottomSheet<void>(
    context: context,
    isScrollControlled: true,
    useSafeArea: true,
    builder: (_) => _AddToPlaylistSheet(
      trackIds: trackIds,
      suggestedName: suggestedName,
      parent: context,
    ),
  );
}

class _AddToPlaylistSheet extends ConsumerWidget {
  const _AddToPlaylistSheet({
    required this.trackIds,
    required this.parent,
    this.suggestedName,
  });

  final List<String> trackIds;
  final String? suggestedName;

  /// Screen that opened the sheet; it outlives the sheet, so dialogs and
  /// toasts are shown through it.
  final BuildContext parent;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final playlists = ref.watch(editablePlaylistsProvider);
    final c = context.colors;

    Future<void> addTo(PlaylistRow p) async {
      final session = await ref.read(sessionProvider.future);
      if (context.mounted) Navigator.of(context).pop();
      if (session == null) return;
      final ok = await session.playlists.addTracks(p.id, trackIds);
      if (!parent.mounted) return;
      unawaited(HapticFeedback.mediumImpact());
      _toast(
        parent,
        ok
            ? 'Added ${plural(trackIds.length, 'song')} to "${p.name}"'
            : '"${p.name}" cannot be changed',
      );
    }

    Future<void> createNew() async {
      Navigator.of(context).pop();
      await createPlaylistFlow(
        parent,
        trackIds: trackIds,
        suggestedName: suggestedName,
      );
    }

    return SafeArea(
      child: ConstrainedBox(
        constraints: BoxConstraints(
          maxHeight: MediaQuery.sizeOf(context).height * 0.7,
        ),
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(
                  Space.gutter, Space.lg, Space.gutter, Space.sm),
              child: Text('Add to playlist', style: context.text.titleLarge),
            ),
            ListTile(
              leading: Container(
                width: 48,
                height: 48,
                decoration: BoxDecoration(
                  color: c.surfaceHigh,
                  borderRadius: BorderRadius.circular(Radii.art),
                ),
                child: const Icon(Icons.add_rounded),
              ),
              title: const Text('New playlist'),
              onTap: createNew,
            ),
            Flexible(
              child: ListView.builder(
                shrinkWrap: true,
                itemCount: playlists.length,
                itemBuilder: (context, i) {
                  final p = playlists[i];
                  return ListTile(
                    leading: SizedBox.square(
                      dimension: 48,
                      child: CoverArt(
                        coverArtId: p.coverArt,
                        fallbackLabel: p.name,
                      ),
                    ),
                    title: Text(p.name,
                        maxLines: 1, overflow: TextOverflow.ellipsis),
                    subtitle: Text(plural(p.songCount, 'song')),
                    onTap: () => addTo(p),
                  );
                },
              ),
            ),
            const SizedBox(height: Space.md),
          ],
        ),
      ),
    );
  }
}

/// Confirms and deletes [playlist]; returns whether it was deleted.
Future<bool> confirmDeletePlaylist(
  BuildContext context,
  PlaylistRow playlist,
) async {
  final container = ProviderScope.containerOf(context, listen: false);
  final ok = await showDialog<bool>(
    context: context,
    builder: (ctx) => AlertDialog(
      title: const Text('Delete playlist?'),
      content: Text('"${playlist.name}" will be removed from your library '
          'and from the server. The songs themselves stay.'),
      actions: [
        TextButton(
          onPressed: () => Navigator.of(ctx).pop(false),
          child: const Text('Cancel'),
        ),
        FilledButton(
          onPressed: () => Navigator.of(ctx).pop(true),
          child: const Text('Delete'),
        ),
      ],
    ),
  );
  if (ok != true) return false;
  final session = await container.read(sessionProvider.future);
  if (session == null) return false;
  await session.playlists.delete(playlist.id);
  return true;
}

/// Renames [playlist] after asking for the new name.
Future<void> renamePlaylistFlow(
  BuildContext context,
  PlaylistRow playlist,
) async {
  final container = ProviderScope.containerOf(context, listen: false);
  final name = await promptPlaylistName(
    context,
    title: 'Rename playlist',
    initial: playlist.name,
    confirmLabel: 'Save',
  );
  if (name == null || name == playlist.name) return;
  final session = await container.read(sessionProvider.future);
  await session?.playlists.rename(playlist.id, name);
}
